    print("대상:",TARGET,"\n적용전 md5:",before)
    if "def fallback_answer(" in src: print("[스킵] 이미 v13.20 적용됨."); sys.exit(0)
    if before!=EXPECT_BEFORE: print("[경고] 적용전 md5가 예상 v1319과 다름. 훅 매칭되면 계속.")
